import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"兵车行","description":"","frontmatter":{"title":"兵车行","date":"2026-11-27T00:00:00.000Z","seq":31,"categories":["美文","唐诗三百首"],"collection":"《唐诗三百首 · 乐府》","tags":["唐诗三百首","唐"],"poem":true,"poem_quote":false,"author":"杜甫","source_book":"唐诗三百首","prev":{"text":"哀王孙","link":"/blogs/唐诗三百首·乐府/哀王孙.html"},"next":{"text":"丽人行","link":"/blogs/唐诗三百首·乐府/丽人行.html"}},"headers":[],"relativePath":"blogs/唐诗三百首·乐府/兵车行.md","filePath":"blogs/唐诗三百首·乐府/兵车行.md"}'),o={name:"blogs/唐诗三百首·乐府/兵车行.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="兵车行" tabindex="-1">兵车行 <a class="header-anchor" href="#兵车行" aria-label="Permalink to &quot;兵车行&quot;">​</a></h1><p class="poem-meta">唐 · 杜甫　·　乐府</p><div class="poem"><p class="poem-stanza">车辚辚，马萧萧，行人弓箭各在腰。</p><p class="poem-stanza">耶娘妻子走相送，尘埃不见咸阳桥。(</p><p class="poem-stanza">娘 一作：“爷”)</p><p class="poem-stanza">牵衣顿足拦道哭，哭声直上干云霄。</p><p class="poem-stanza">道旁过者问行人，行人但云点行频。</p><p class="poem-stanza">或从十五北防河，便至四十西营田。</p><p class="poem-stanza">去时里正与裹头，归来头白还戍边。</p><p class="poem-stanza">边庭流血成海水，武皇开边意未已。</p><p class="poem-stanza">君不闻，汉家山东二百州，千村万落生荆杞。</p><p class="poem-stanza">纵有健妇把锄犁，禾生陇亩无东西。</p><p class="poem-stanza">况复秦兵耐苦战，被驱不异犬与鸡。</p><p class="poem-stanza">长者虽有问，役夫敢申恨？</p><p class="poem-stanza">且如今年冬，未休关西卒。</p><p class="poem-stanza">县官急索租，租税从何出？</p><p class="poem-stanza">信知生男恶，反是生女好。</p><p class="poem-stanza">生女犹得嫁比邻，生男埋没随百草。</p><p class="poem-stanza">君不见，青海头，古来白骨无人收。</p><p class="poem-stanza">新鬼烦冤旧鬼哭，天阴雨湿声啾啾！</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
